def count_ways(target_sum, coin_values):
    dp = [0] * (target_sum + 1)
    dp[0] = 1
    for coin in coin_values:
        for i in range(coin, target_sum + 1):
            dp[i] += dp[i - coin]
    return dp[target_sum]

